/**
 * `doc/design/platform-errors.md`'s *What Lingtai recognises today*, rendered
 * from the table (0108 §19) so it cannot name a line that has moved.
 *
 * `pnpm docs:errors` writes it between two markers; the unit test fails with
 * that command's name when the committed section differs. The hand-written
 * sections of the page are outside the markers and are never touched.
 */
import { FAILURE_ROWS, type FailureRow } from './classify.ts'

export const RECOGNISED_BEGIN =
  '<!-- generated by `pnpm docs:errors` from packages/domain/src/failure/classify.ts — do not edit -->'
export const RECOGNISED_END = '<!-- end generated -->'

interface Section {
  readonly title: string
  readonly of: (row: FailureRow) => boolean
  /** What the rows do not recognise, and what is not a row at all. */
  readonly unmatched: string
}

const SECTIONS: readonly Section[] = [
  {
    title: 'GitHub API',
    of: (r) => r.platform === 'github',
    unmatched:
      "`classify` reads it for `asLinkCall`, which keeps a rate-limited 403 from being called a missing permission. `githubJson` keeps the status, the body's `message` and the response's `x-ratelimit-remaining`, `x-ratelimit-reset` and `retry-after` (null when absent or not plain digits); `classify` reads the first and last. Errors from the `gh` CLI carry no headers. Nothing retries or waits on these fields yet.",
  },
  {
    title: 'git',
    of: (r) => r.platform === 'git',
    unmatched:
      'The rows are tried in this order, and the first to match wins, so a real rejection is never read as transient. `retryUnreachable` retries `remote-error` and `unreachable` after the waits their rows name; then the lane refuses `unreachable` or `remote-error`, both `RefusalReason`s owned by `lingtai`. Push protection, a pre-receive hook, `GH001` and the 2 GiB limit have no row of their own.',
  },
  {
    title: 'Claude Code',
    of: (r) => r.platform === 'runtime' && r.runtime === 'claude-code',
    unmatched:
      'A run is `never-started` on three facts, no words (`neverStarted`). A crash whose detail is the account-limit sentence locks the account, and `standDown` says until when. Nothing matches a 5xx, a 529, a 429 or an *Attention Required* page: today every one of them is a crash and holds for a person.',
  },
  {
    title: 'Codex',
    of: (r) => r.platform === 'runtime' && r.runtime === 'codex',
    unmatched:
      "`codexClose` makes a `turn.failed` with no agent message `never-started`. The row is tried before Claude Code's, whose looser pattern would claim the first form. Nothing reads `insufficient_quota`, `server_is_overloaded` or a status code.",
  },
]

/** The bullets between the markers, one per platform, rows in table order. */
export function renderRecognised(): string {
  const bullets = SECTIONS.map((section) => {
    const rows = FAILURE_ROWS.filter(section.of)
    const lines = rows.map((r) => `  - \`${r.kind}\`: ${r.says}`)
    return [`- **${section.title}.** ${section.unmatched}`, ...lines].join('\n')
  })
  return bullets.join('\n')
}

/** `doc` with the section between the markers replaced by the rendered one. Throws when a marker is missing. */
export function spliceRecognised(doc: string): string {
  const a = doc.indexOf(RECOGNISED_BEGIN)
  const b = doc.indexOf(RECOGNISED_END)
  if (a < 0 || b < a) throw new Error('platform-errors.md has no generated section: the markers are missing')
  return `${doc.slice(0, a + RECOGNISED_BEGIN.length)}\n\n${renderRecognised()}\n\n${doc.slice(b)}`
}
